using System;
using System.IO;
using System.Collections.Generic;
class PassengerTraitTests {
 static int n;static void Check(bool b,string s){n++;if(!b)throw new Exception(s);}static void Reject(Action a,string s){bool bad=false;try{a();}catch(ArgumentException){bad=true;}Check(bad,s);}
 static PassengerBehaviorState Make(PassengerType type,params string[] traits){var p=PassengerBehaviorState.Create("trait-test",type);p.PresetId="trait-test";p.PresetName="복합 승객";p.PresetIntro="";p.PresetPool=PassengerType.Comfort;p.PresetRepresentative=PassengerType.General;p.PresetTraits=traits;return p;}
 static void Main(string[] args){try{Run();ConfigurationChecks(args[0]);Console.WriteLine("PASS PassengerTraitTests "+n);}catch(Exception e){Console.WriteLine("FAIL "+e);Environment.Exit(1);}}
 static void ConfigurationChecks(string catalog){
  ContentTuning.ConfigureCatalog(File.ReadAllText(catalog));string baseline=ContentTuning.CaptureJson();
  var profile=ContentJson.Object(ContentJson.Parse(baseline));ContentJson.Array(profile["values"]).RemoveAll(o=>{string id=(string)ContentJson.Object(o)["id"];return id.StartsWith("trait.")||id.StartsWith("effect.nausea.")||id.StartsWith("effect.temperature.")||id.StartsWith("effect.umbrella.")||id.StartsWith("choice.request.Quiet.Accept.end.failure.")||id=="request.LocalChat.reply.SmallTalk"||id=="request.Quiet.reply.SmallTalkViolation";});profile["contentHash"]=ContentTuning.ComputeHash(profile);string old=ContentJson.Stringify(profile);ContentTuning.UseJson(old);Check(ContentTuning.CaptureJson()==old,"old extension-free profile preserved exactly");ContentTuning.ValidateJson(ContentTuning.UpgradeJson(old));
  ContentJson.Array(profile["values"]).Add(new Dictionary<string,object>{{"id","effect.nausea.rate"},{"value",".35"}});profile["contentHash"]=ContentTuning.ComputeHash(profile);Reject(()=>ContentTuning.UseJson(ContentJson.Stringify(profile)),"partial trait extension rejected");ContentTuning.UseJson(baseline);
  var p=Make(PassengerType.General,"body.nausea");p.PresetOverrides=new[]{new PassengerOverride{id="effect.nausea.eventPercent",value="0"}};p.Board();p.Advance(300,false,true,.5f,100);Check(!p.NauseaPlanned&&!p.NauseaIncident&&p.TraitAction.Length==0,"individual zero probability remains no event");p=p.Copy();p.Validate();
  p=Make(PassengerType.General,"body.nausea");p.PresetOverrides=new[]{new PassengerOverride{id="effect.nausea.warning",value="80"}};Reject(()=>p.Validate(),"saved effective per-preset nausea relation rejected");
  p=Make(PassengerType.General,"item.wetUmbrella");p.PresetOverrides=new[]{new PassengerOverride{id="effect.umbrella.prepareSeconds",value="0"}};p.Respond(0,true);Check(p.Board()&&p.DirtEvents.Length==0,"individual zero wrapping seconds completes immediately");p.Validate();
  p=Make(PassengerType.Food,"item.food","body.temperatureSensitive");p.PresetOverrides=new[]{new PassengerOverride{id="choice.type.Food.1.immediate.satisfaction",value="7"}};p.Board();p.Respond(1,true);Check(p.TraitAction=="temperature"&&p.SelectedEffect.Contains("7"),"primary selected effect stays accurate while next trait opens");p.Validate();ContentTuning.UseJson(baseline);
 }
 static void Run(){
  var legacy=PassengerBehaviorState.Create("old",PassengerType.General);legacy.TraitVersion=0;legacy.NauseaChoice=legacy.UmbrellaChoice=legacy.TemperatureSetting=0;legacy.Validate();Check(legacy.NauseaChoice==-1&&legacy.UmbrellaChoice==-1&&legacy.TemperatureSetting==-1,"Unity absent legacy fields normalize neutrally");
  Reject(()=>{var corrupt=Make(PassengerType.General,"body.nausea");corrupt.NauseaChoice=1;corrupt.Validate();},"preboarding nausea response rejected");
  Reject(()=>{var corrupt=Make(PassengerType.General,"body.nausea");corrupt.Board();corrupt.NauseaIncident=true;corrupt.Validate();},"unprotected incident cannot omit dirt");
  Reject(()=>{var corrupt=Make(PassengerType.General,"item.wetUmbrella");corrupt.Respond(1,true);corrupt.Board();corrupt.UmbrellaDirtOccurred=false;corrupt.Validate();},"unwrapped boarded umbrella cannot omit dirt");
  var definition=new PassengerPresetDefinition{id="sleep-food",name="잠과 음식",intro="",pool="Sleeping",traits=new[]{"body.sleepy","item.food"}};PassengerPresetCatalog.Validate(definition);Check(definition.ActionModule=="Food","cargo action independent of trait ordering");
  var p=Make(PassengerType.Food,"body.sleepy","item.food");p.Variant=0;p.Respond(1,true);p.Board();p.Advance(25,false,true,.6f,100);Check(p.Sleeping&&!p.ConsumptionOccurred,"sleeping food never consumes");p=p.Copy();p.Validate();p.ObserveJolt();p.Advance(1,false,true,.6f,100);Check(p.ConsumptionOccurred,"awake food can consume after jolt");
  p=Make(PassengerType.Luggage,"body.sleepy","item.luggage");Check(!p.Board(),"cargo still blocks boarding");p.Respond(0,true);p.Advance(10,true,false,0,100);Check(p.Board(),"cargo prepared");p.Advance(40,false,true,.5f,100);Check(p.Sleeping,"loaded passenger falls asleep");p.Arrive();Check(!p.Finish(true),"sleep plus unloading blocks finish");p.Advance(10,true,false,1,100);p.Validate();

  p=Make(PassengerType.General,"item.wetUmbrella");Check(p.TraitAction=="umbrella"&&!p.Board()&&!p.Respond(0,false),"umbrella actual safe-stop boarding gate");Check(p.Respond(0,true)&&p.TraitWorkRemaining==6,"wrapped umbrella has real work");p.Advance(6,true,false,0,100,true);Check(!p.Board(),"paused wrapping frozen");p.Advance(3,true,false,0,100);p=p.Copy();p.Validate();p.Advance(3,true,false,0,100);Check(p.Board()&&p.DirtEvents.Length==0,"wrap resumes without dirt");
  p=Make(PassengerType.General,"item.wetUmbrella");p.Respond(1,true);Check(p.DirtEvents.Length==0,"no umbrella soil before actual board");p.Board();p.BindEffectTrip("umbrella-trip");var care=new VehicleCare();foreach(var e in p.DirtEvents)care.Soil(e.Id,e.Amount);p=p.Copy();p.Validate();foreach(var e in p.DirtEvents)care.Soil(e.Id,e.Amount);Check(care.Cleanliness==97&&p.DirtEvents[0].Id=="umbrella-trip:umbrella","umbrella once per trip across restore");p.ExitCancelled();p.Validate();Check(p.DirtEvents.Length==1,"cancellation preserves actual soil");
  p=Make(PassengerType.General,"body.temperatureSensitive");p.Board();Check(p.TraitAction=="temperature"&&p.Dialogue.Contains(p.TemperaturePreference==0?"따뜻하게":"시원하게"),"actual desired cabin setting visible");Check(!p.Respond(p.TemperaturePreference,false),"unsafe HVAC response rejected");p.Respond(1-p.TemperaturePreference,true);p.Advance(20,false,true,.3f,100,true);Check(p.TraitSatisfactionDelta==0,"paused comfort evaluation frozen");p.Advance(20,false,true,.3f,100);Check(p.TraitSatisfactionDelta==-2&&p.TemperatureCorrectionPending,"sustained wrong setting evaluated with correction choice");p=p.Copy();p.Validate();Check(p.Dialogue.Contains("다시"),"correction survives snapshot");p.Respond(p.TemperaturePreference,true);p.Advance(14,false,true,.5f,100);Check(p.TraitSatisfactionDelta==-2,"correct choice needs real comfort time");p.Advance(1,false,true,.5f,100);Check(p.TraitSatisfactionDelta==3&&!p.HasChoice,"comfort replaces previous result once");p.Arrive();p.Finish(true);p.Validate();p.Advance(50,false,true,1,100);Check(p.TraitSatisfactionDelta==3,"settlement freezes comfort");
  p=Make(PassengerType.General,"body.nausea");p.Board();p.Advance(60,false,true,.3f,100);Check(p.TraitAction=="nausea"&&p.Dialogue.Contains("울렁"),"actual moving accumulation opens nausea care");float before=p.NauseaLevel;p.Respond(0,true);p.Advance(4,true,false,.3f,100);p=p.Copy();p.Validate();p.Advance(100,false,true,.4f,100,true);Check(p.NauseaRestRemaining==4&&p.NauseaLevel==before,"paused rest freezes both timers");p.Advance(4,true,false,.4f,100);Check(p.NauseaLevel==0&&p.TraitWorkRemaining==0,"completed safe rest relieves nausea");p.Advance(220,false,true,.6f,100);Check(p.NauseaIncident&&p.NauseaDirtOccurred&&p.DirtEvents.Length==1,"later unprotected incident actual dirt");p=p.Copy();p.Validate();Check(!p.Respond(1,true)&&p.NauseaDirtOccurred,"incident cannot be reversed by late bag");
  p=Make(PassengerType.General,"body.nausea");p.Board();p.Advance(60,false,true,.3f,100);p.Respond(1,true);p.Advance(220,false,true,.6f,100);p.Validate();Check(p.NauseaIncident&&!p.NauseaDirtOccurred&&p.DirtEvents.Length==0,"bag prevents only future dirt");
  p=Make(PassengerType.General,"body.nausea");p.Board();var situation=PassengerSituationState.Create("n",0,0,0);situation.ApplyPhysicalObservation(p,0,0,1);Check(p.NauseaLevel==0,"necessary brake does not add rough nausea");situation.ApplyPhysicalObservation(p,1,0,1);Check(p.NauseaLevel==12,"actual rough brake accumulates");situation.ApplyPhysicalObservation(p,1,0,1);Check(p.NauseaLevel==12,"same physical counters never replay nausea");
  Reject(()=>{var bad=p.Copy();bad.NauseaRestRemaining=float.NaN;bad.Validate();},"nonfinite trait timer rejected");Reject(()=>{var bad=Make(PassengerType.General,"item.wetUmbrella");bad.UmbrellaDirtOccurred=true;bad.Validate();},"invented unboarded dirt rejected");
  p=Make(PassengerType.Food,"item.food","body.sleepy","item.wetUmbrella","body.nausea","body.temperatureSensitive");p.Respond(0,true);p.Respond(0,true);p.Advance(6,true,false,0,100);p.Board();Check(p.TraitAction=="temperature","combined trait queue reaches cabin setting");p.Respond(p.TemperaturePreference,true);p.Advance(60,false,true,.5f,100);Check(p.Sleeping&&!p.ConsumptionOccurred&&!p.HasChoice,"combined sleeping suppresses food and queued dialogue");p.ObserveJolt();Check(p.TraitAction=="nausea","wake exposes queued nausea warning");p.Respond(1,true);p=p.Copy();p.Validate();

 }
}
